// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        uint256 boundAmount = bound(amount, 0, type(uint256).max);

        // Ensure the caller is the owner so onlyOwner modifier passes
        // we already are address(this) which is owner from constructor

        c.AdjustBetAmounts(boundAmount);

        // General rule: after AdjustBetAmounts(amount), betLimit equals amount
        assertTrue(c.currentBetLimit() == boundAmount);
    }
}

